#define main original_asta_main
#include "../asta-cuda/main.cu"
#undef main
#include <cstdint>
#include <string>
struct Case{int b;int actualhead;std::vector<float>input,expected,got;std::vector<int>flags,actualflags;float*d;int*finished,*head;};
int main(){std::vector<Case>cases;const int A=13,B=17,m=A*B-1;for(int b:{1,32,65,129,256}){Case c;c.b=b;c.input.resize(A*B*b);c.expected.resize(c.input.size());c.got.resize(c.input.size());c.flags.resize(A*B);c.actualflags.resize(A*B);for(int i=0;i<int(c.input.size());i++)c.input[i]=float((73*i+19)%65521-32760)/64;for(int row=0;row<A;row++)for(int col=0;col<B;col++)for(int lane=0;lane<b;lane++)c.expected[(col*A+row)*b+lane]=c.input[(row*B+col)*b+lane];for(int i=0;i<m;i++)c.flags[i]=(i*A)%m==i?0:1;c.flags[m]=0;cudaMalloc(&c.d,4*c.input.size());cudaMalloc(&c.finished,4*A*B);cudaMalloc(&c.head,4);cases.push_back(c);}
 auto one=[&](Case&c){cudaMemcpy(c.d,c.input.data(),4*c.input.size(),cudaMemcpyHostToDevice);cudaMemset(c.finished,0,4*A*B);cudaMemset(c.head,0,4);cudaDeviceSynchronize();auto t=std::chrono::steady_clock::now();PTTWAC_soa_asta<<<16,64>>>(A,B,c.b,c.d,c.finished,c.head);cudaDeviceSynchronize();double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();cudaMemcpy(c.got.data(),c.d,4*c.got.size(),cudaMemcpyDeviceToHost);cudaMemcpy(c.actualflags.data(),c.finished,4*A*B,cudaMemcpyDeviceToHost);int head;cudaMemcpy(&head,c.head,4,cudaMemcpyDeviceToHost);c.actualhead=head;bool ok=c.got==c.expected&&c.actualflags==c.flags&&head==m+16;return std::make_pair(elapsed,ok);};for(auto&c:cases)for(int i=0;i<10;i++)one(c);
 for(int trial=1;trial<=5;trial++){double total=0;bool ok=true;std::vector<uint32_t>output;
 for(auto&c:cases){for(int rep=0;rep<100;rep++){auto v=one(c);total+=v.first/100;ok&=v.second;}size_t start=output.size();output.resize(start+c.got.size());memcpy(output.data()+start,c.got.data(),4*c.got.size());for(int v:c.actualflags)output.push_back(uint32_t(v));output.push_back(uint32_t(c.actualhead));}
 std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/trial_"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"timing_region\":\"sum_five_payloads_perlaunch_sync_inplace_transpose_means\",\"jit_excluded\":true,\"internal_repeats\":100,\"all_internal_repeats_checked\":true,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",output.size(),ok?0:1,path.c_str(),output.size());if(!ok)return 9;}}
